#!/usr/bin/env python3
"""Apply the Schreiber AI brand v2 to decks generated by build_presentation.py (BEN Engine Rev 2).

    python3 scripts/brand_deck.py                      # both decks
    python3 scripts/brand_deck.py docs/presentation/index.html

Run it after every rebuild of a deck (the generator cannot be edited). Idempotent: a previous
injection (between <!--bv2:start--> / <!--bv2:end--> markers and bv2- attributes) is removed first.

What it injects:
* brand/v2/deck-theme.css (inline, after the generator's own <style>)
* the brand fonts as data URIs (Archivo variable wdth+wght, IBM Plex Sans 400/600, IBM Plex Mono 500/600,
  Latin subset) so a deck mailed as one file still renders in the brand type; --link-fonts uses
  relative links to brand/v2/fonts/fonts.css instead
* the v2 lockup (brand/v2/lockup-signal.svg; lockup-deep.svg for print) in the header, the stacked
  lockup on slide 1, and a data plate band at the bottom of every slide.
Rev 1 decks are archived under archive/rev1/docs/.
"""
from __future__ import annotations

import base64
import html
import os
import re
import sys
from pathlib import Path

REPO = Path(__file__).resolve().parent.parent
BRAND = REPO / "brand" / "v2"
DECKS = [REPO / "docs" / "presentation" / "index.html", REPO / "docs" / "investors" / "deck" / "index.html"]
FONTS = [("Archivo", "archivo-latin-wdth-normal.woff2", "100 900", "62% 125%"),
         ("IBM Plex Sans", "ibm-plex-sans-latin-400-normal.woff2", "400", None),
         ("IBM Plex Sans", "ibm-plex-sans-latin-600-normal.woff2", "600", None),
         ("IBM Plex Mono", "ibm-plex-mono-latin-500-normal.woff2", "500", None),
         ("IBM Plex Mono", "ibm-plex-mono-latin-600-normal.woff2", "600", None)]
LEGAL = "Schreiber AI is a Schreiber Holding LLC company."


def svg_uri(name: str) -> str:
    return "data:image/svg+xml;base64," + base64.b64encode((BRAND / f"{name}.svg").read_bytes()).decode()


def font_css(link: bool, deck: Path) -> str:
    if link:
        rel = os.path.relpath(BRAND / "fonts" / "fonts.css", deck.parent)
        return f'<link rel="stylesheet" href="{rel}">'
    out = []
    for fam, f, w, st in FONTS:
        b64 = base64.b64encode((BRAND / "fonts" / f).read_bytes()).decode()
        out.append(f"@font-face{{font-family:'{fam}';font-style:normal;font-display:swap;font-weight:{w};" + (f"font-stretch:{st};" if st else "")
                   + f"src:url(data:font/woff2;base64,{b64}) format('woff2')}}")
    return "<style>" + "".join(out) + "</style>"


def strip(s: str) -> str:
    s = re.sub(r'<span class="bv2-legal">.*?</span>', "", s, flags=re.S)
    s = re.sub(r"<!--bv2:start-->.*?<!--bv2:end-->", "", s, flags=re.S)
    s = re.sub(r'<div class="bv2-dp"[^>]*>.*?</div></div>', "", s, flags=re.S)
    s = re.sub(r'<img class="bv2-[^"]*"[^>]*>', "", s)
    s = re.sub(r'<span class="bv2-rule"[^>]*></span>', "", s)
    s = re.sub(r'<p class="bv2-by">.*?</p>', "", s, flags=re.S)
    s = s.replace(' bv2-title"', '"')
    return s


def brand(deck: Path, link_fonts: bool = False) -> None:
    s = deck.read_text(encoding="utf-8")
    s = strip(s)
    title = re.search(r"<title>(.*?)</title>", s, re.S)
    title_txt = html.unescape(title.group(1)) if title else "BEN Engine"
    short = title_txt.split("—")[-1].strip() if "—" in title_txt else title_txt
    css = (BRAND / "deck-theme.css").read_text(encoding="utf-8")
    inject = f"<!--bv2:start-->{font_css(link_fonts, deck)}<style>{css}</style><link rel=\"icon\" href=\"{svg_uri('small-mark-32-signal')}\"><!--bv2:end-->"
    s = s.replace("</head>", inject + "</head>", 1)
    # header lockup
    s = re.sub(r"<header><strong>", "<header><strong>"
               f'<img class="bv2-lockup screen" src="{svg_uri("lockup-signal")}" alt="Schreiber AI" height="22">'
               f'<img class="bv2-lockup print" src="{svg_uri("lockup-deep")}" alt="Schreiber AI" height="22">'
               '<span class="bv2-rule" aria-hidden="true"></span>', s, count=1)
    # slides: band at the bottom of every slide, lockup on the title slide
    slides = list(re.finditer(r'<section class="slide"( id="slide-(\d+)")', s))
    total = len(slides)
    out, pos = [], 0
    for m in re.finditer(r'(<section class="slide")( id="slide-(\d+)"[^>]*>)(.*?)(</section>)', s, re.S):
        n = int(m.group(3))
        body = m.group(4)
        cls = m.group(1)
        if n == 1:
            cls = '<section class="slide bv2-title"'
            body = (f'<img class="bv2-title-lockup screen" src="{svg_uri("stack-signal")}" alt="Schreiber AI">'
                    f'<img class="bv2-title-lockup print" src="{svg_uri("stack-deep")}" alt="Schreiber AI">'
                    '<p class="bv2-by">BEN Engine, by Schreiber AI · Rev 2</p>') + body
        band = ('<div class="bv2-dp" aria-hidden="true"><div class="dp"><span><b>Schreiber AI</b></span><i></i><span>BEN Engine</span><i class="opt"></i>'
                f'<span class="opt">{html.escape(short)}</span><i></i><span>Rev 2</span><span class="grow"></span><span>{n:02d} / {total:02d}</span></div></div>')
        out.append(s[pos:m.start()] + cls + m.group(2) + body + band + m.group(5))
        pos = m.end()
    out.append(s[pos:])
    s = "".join(out)
    # legal line in the page footer
    s = re.sub(r"(<footer>)", r'\1<span class="bv2-legal"><!--bv2:start-->' + LEGAL + "<!--bv2:end--></span>", s, count=1) if "<footer>" in s else s
    deck.write_text(s, encoding="utf-8")
    print(f"branded {deck.relative_to(REPO)}: {total} slides")


if __name__ == "__main__":
    args = [a for a in sys.argv[1:] if not a.startswith("--")]
    for d in ([Path(a).resolve() for a in args] or DECKS):
        brand(d, link_fonts="--link-fonts" in sys.argv)
